#include "web_pages.h"

namespace web_pages {

std::string model_test_html() {
    return std::string(R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">)HTML") + common_style() + R"HTML(</head><body><div class="top"><nav class="nav"><span class="brand">模型识别测试</span><a class="back" href="/">返回服务选择</a></nav></div><main class="wrap"><section class="panel"><h2>模型识别测试</h2><div class="model-control"><label for="modelSelect">测试模型</label><span class="model-current">当前：<strong id="currentModel">读取中…</strong></span><select id="modelSelect"></select><button id="switchModel" onclick="changeModel()">切换模型</button></div><div id="modelMessage" class="muted" style="margin-top:8px"></div><div class="test-modes"><button id="datasetMode" class="active" onclick="selectMode('dataset')">数据集全量测试</button><button id="folderMode" onclick="selectMode('folder')">未分类文件夹识别</button></div><div id="datasetForm"><div class="notice">按 <b>/home/root/image/dataset/&lt;类别名&gt;/</b> 测试并统计正确率。错误图片会复制到 error 目录，并显示在页面下方。</div><button id="startDataset" class="primary" onclick="runDatasetTest()">开始全量测试</button></div><div id="folderForm" hidden><div class="notice">输入设备上的文件夹绝对路径，将递归识别其中的 PNG、JPG、JPEG、BMP 图片。此模式没有真实标签，不计算正确率。</div><div class="folder-form"><input id="folderPath" class="grow" value="/home/root/image/" placeholder="/home/root/image/unclassified"><button id="startFolder" class="primary" onclick="runFolderTest()">识别文件夹</button></div></div><div class="progress"><div id="progressBar"></div></div><div class="row"><strong id="testMessage">尚未开始测试</strong><span class="muted" id="progressText">0 / 0</span></div><div id="datasetSummary"><div class="summary"><div class="metric"><span>总体正确率</span><strong id="overallAccuracy">—</strong></div><div class="metric"><span>正确</span><strong id="totalCorrect">0</strong></div><div class="metric"><span>错误</span><strong id="totalError">0</strong></div><div class="metric"><span>耗时</span><strong id="elapsed">0 s</strong></div></div><div id="legend" class="legend"></div><div class="table-wrap"><table class="results"><thead><tr><th>真实类别</th><th>正确率</th><th>正确</th><th>错误</th><th>识别结果分布</th></tr></thead><tbody id="resultRows"><tr><td colspan="5" class="muted">尚无测试结果</td></tr></tbody></table></div></div><div class="result-title"><h2 id="imageResultTitle">错误图片</h2><span id="resultCount" class="muted">0 张</span></div><div id="imageResults" class="result-gallery"></div></section></main><script>
let selectedMode='dataset',lastResultCount=-1,testTimer=null;const colors=['#222','#d67b20','#447a62','#a44b4b','#5876a3','#8a6d9e','#777'];function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function api(p,o){let r=await fetch(p,o);return r.json()}async function refreshModels(){let m=await api('/api/models');currentModel.innerText=m.current||'未加载';modelSelect.innerHTML=m.models.map(n=>`<option value="${esc(n)}" ${n===m.current?'selected':''}>${esc(n)}</option>`).join('');switchModel.disabled=!m.models.length;modelMessage.innerText=m.models.length?'检测到 '+m.models.length+' 个可用模型':'未检测到文件完整的模型'}async function changeModel(){let name=modelSelect.value;if(!name)return;switchModel.disabled=true;let r=await api('/api/models/switch',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'name='+encodeURIComponent(name)});modelMessage.innerText=r.message;await refreshModels();await refreshTest()}function stopTestPolling(){if(testTimer){clearInterval(testTimer);testTimer=null}}function startTestPolling(){stopTestPolling();testTimer=setInterval(refreshTest,1500)}function selectMode(m){selectedMode=m;datasetMode.classList.toggle('active',m==='dataset');folderMode.classList.toggle('active',m==='folder');datasetForm.hidden=m!=='dataset';folderForm.hidden=m!=='folder'}async function runDatasetTest(){let r=await api('/api/test/start',{method:'POST'});if(!r.started){alert((r.state&&r.state.message)||'测试正在运行或启动失败');await refreshTest();return}selectMode('dataset');startTestPolling();await refreshTest()}async function runFolderTest(){let path=folderPath.value.trim();if(!path){alert('请输入设备上的文件夹路径');return}let r=await api('/api/test/folder/start',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'path='+encodeURIComponent(path)});if(!r.started){alert((r.state&&r.state.message)||'无法启动文件夹识别');await refreshTest();return}selectMode('folder');startTestPolling();await refreshTest()}function renderImageResults(s){resultCount.innerText=s.results.length+' 张';imageResultTitle.innerText=s.mode==='folder'?'逐张识别结果':'错误图片';imageResults.innerHTML=s.results.map(r=>`<article class=result-card><a href="/api/test/result-image?id=${r.id}" target=_blank><img loading=lazy src="/api/test/result-image?id=${r.id}&t=${s.finished?1:s.processed}"></a><strong>${esc(r.name)}</strong><small>${s.mode==='dataset'?`真实：${esc(r.true_class)}<br>`:''}预测：${esc(r.predicted_class)} · ${(100*r.confidence).toFixed(2)}%</small></article>`).join('')||'<span class=muted>暂无图片结果</span>'}async function refreshTest(){let s=await api('/api/test/status');let pct=s.total?100*s.processed/s.total:0;progressBar.style.width=pct+'%';progressText.innerText=`${s.processed} / ${s.total} (${pct.toFixed(1)}%)`;testMessage.innerText=s.message;startDataset.disabled=s.running;startFolder.disabled=s.running;datasetMode.disabled=s.running;folderMode.disabled=s.running;modelSelect.disabled=s.running;switchModel.disabled=s.running||!modelSelect.options.length;if(s.running)selectMode(s.mode);datasetSummary.hidden=selectedMode==='folder';let evaluated=s.correct+s.error;overallAccuracy.innerText=evaluated?(100*s.correct/evaluated).toFixed(1)+'%':'—';totalCorrect.innerText=s.correct;totalError.innerText=s.error+(s.load_failed?` (+${s.load_failed} 加载失败)`:'');elapsed.innerText=(s.elapsed_ms/1000).toFixed(1)+' s';legend.innerHTML=s.classes.map((c,i)=>`<span><i class=dot style="background:${colors[i%colors.length]}"></i>${esc(c.name)}</span>`).join('');resultRows.innerHTML=s.classes.length?s.classes.map((c,i)=>{let acc=c.total?100*c.correct/c.total:0;let bars=c.predictions.map((n,j)=>`<i class=seg title="${esc(s.classes[j].name)}: ${n}" style="width:${c.total?100*n/c.total:0}%;background:${colors[j%colors.length]}"></i>`).join('');return `<tr><td><b>${esc(c.name)}</b><br><span class=muted>${c.total} 张</span></td><td><b>${acc.toFixed(1)}%</b></td><td>${c.correct}</td><td>${c.error}</td><td class=dist><div class=bar>${bars}</div></td></tr>`}).join(''):'<tr><td colspan=5 class=muted>尚无分类统计</td></tr>';if(lastResultCount!==s.results.length||s.finished){renderImageResults(s);lastResultCount=s.results.length}if(!s.running)stopTestPolling()}Promise.all([refreshModels(),refreshTest()]);
</script></body></html>)HTML";
}

} // namespace web_pages
